use std::{
    collections::{BTreeMap, HashMap},
    env, fs,
    path::{Path, PathBuf},
};

use serde::Deserialize;

type GenResult<T> = Result<T, Box<dyn std::error::Error>>;

pub fn run() -> GenResult<()> {
    let manifest_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR")?);
    let schemas_dir = manifest_dir.join("schemas");
    let schema_path = schemas_dir.join("message_schemas.json");
    let overrides_path = schemas_dir.join("codegen_overrides.json");
    let out_path = manifest_dir.join("src/messages/generated.rs");

    println!(
        "cargo:rerun-if-changed={}",
        manifest_dir.join("build.rs").display()
    );
    println!(
        "cargo:rerun-if-changed={}",
        manifest_dir.join("codegen/mod.rs").display()
    );
    println!("cargo:rerun-if-changed={}", schema_path.display());
    println!("cargo:rerun-if-changed={}", overrides_path.display());

    let schemas: Vec<MessageSchema> = read_json(&schema_path)?;
    let overrides: CodegenOverrides = read_json(&overrides_path)?;

    let generated_types = collect_generated_types(&schemas, &overrides);
    let mut out = String::new();
    out.push_str("// @generated by vivo-msgpack build.rs; do not edit by hand.\n");
    out.push_str("#[allow(clippy::all)]\n");
    out.push_str("#[allow(dead_code)]\n");
    out.push_str("#[allow(non_snake_case)]\n");
    out.push_str("#[allow(unused_mut)]\n");
    out.push_str("#[allow(unused_variables)]\n");
    out.push_str("pub mod generated {\n");
    out.push_str(
        "    use crate::msgpack::{MsgpackReader, write_array_len, write_bin, write_bool, write_f32, write_f64, write_i8, write_i16, write_i32, write_i64, write_str};\n",
    );
    out.push_str("    use crate::Result;\n\n");
    emit_descriptors(&mut out, &schemas);
    emit_vec_helpers(&mut out);
    emit_typed_module(&mut out, &schemas, &overrides, &generated_types);
    out.push_str("}\n\n");
    emit_facade_modules(&mut out, &overrides, &generated_types);

    write_if_changed(&out_path, &out)?;
    Ok(())
}

fn read_json<T: for<'de> Deserialize<'de>>(path: &Path) -> GenResult<T> {
    Ok(serde_json::from_slice(&fs::read(path)?)?)
}

fn write_if_changed(path: &Path, content: &str) -> GenResult<()> {
    if let Ok(existing) = fs::read_to_string(path) {
        if existing == content {
            return Ok(());
        }
    }
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    fs::write(path, content)?;
    Ok(())
}

#[derive(Debug, Clone, Deserialize)]
struct MessageSchema {
    class: String,
    simple_name: String,
    package: Option<String>,
    source: Option<String>,
    message_kind: Option<String>,
    bid: Option<u16>,
    cid: Option<u16>,
    encoding: Option<String>,
    #[serde(default)]
    msgpack_fields_effective: Vec<FieldSchema>,
}

#[derive(Debug, Clone, Deserialize)]
struct FieldSchema {
    name: String,
    #[serde(rename = "type")]
    ty: String,
    msgpack: Option<MsgpackOrder>,
}

#[derive(Debug, Clone, Copy, Deserialize)]
struct MsgpackOrder {
    order: i32,
    #[serde(default)]
    since: i32,
}

#[derive(Debug, Default, Deserialize)]
struct CodegenOverrides {
    #[serde(default)]
    manual_types: Vec<ManualType>,
    #[serde(default)]
    modules: Vec<ModuleOverride>,
}

#[derive(Debug, Deserialize)]
struct ManualType {
    simple_name: String,
    bid: Option<u16>,
    cid: Option<u16>,
    message_kind: Option<String>,
    #[serde(default)]
    fields: Vec<ManualField>,
}

#[derive(Debug, Deserialize)]
struct ManualField {
    name: String,
    rust_type: String,
    write: String,
    fallback: Option<String>,
}

#[derive(Debug, Deserialize)]
struct ModuleOverride {
    name: String,
    #[serde(default)]
    exports: Vec<String>,
    #[serde(default)]
    constants: Vec<ModuleConstant>,
}

#[derive(Debug, Deserialize)]
struct ModuleConstant {
    name: String,
    message: Option<String>,
    value: Option<String>,
    #[serde(rename = "type")]
    ty: Option<String>,
    literal: Option<String>,
}

#[derive(Debug, Clone)]
struct GeneratedType {
    rust_name: String,
    bid: Option<u16>,
    cid: Option<u16>,
}

struct GeneratedTypeIndex {
    by_simple: HashMap<String, GeneratedType>,
    by_class: HashMap<String, GeneratedType>,
}

fn collect_generated_types(
    schemas: &[MessageSchema],
    overrides: &CodegenOverrides,
) -> GeneratedTypeIndex {
    let mut base_counts = BTreeMap::<String, usize>::new();
    for schema in schemas
        .iter()
        .filter(|schema| should_generate_reflective(schema))
    {
        let base = sanitize_pascal(&schema.simple_name);
        *base_counts.entry(base).or_default() += 1;
    }
    for manual in &overrides.manual_types {
        let base = sanitize_pascal(&manual.simple_name);
        *base_counts.entry(base).or_default() += 1;
    }

    let mut by_simple = HashMap::new();
    let mut by_class = HashMap::new();
    let mut used_names = HashMap::<String, usize>::new();
    for schema in schemas
        .iter()
        .filter(|schema| should_generate_reflective(schema))
    {
        let mut rust_name = unique_type_name(schema, &base_counts);
        if used_names.contains_key(&rust_name) {
            rust_name = format!("{rust_name}Class{:08x}", stable_hash(&schema.class));
        }
        *used_names.entry(rust_name.clone()).or_default() += 1;
        let generated = GeneratedType {
            rust_name,
            bid: schema.bid,
            cid: schema.cid,
        };
        by_simple.insert(schema.simple_name.clone(), generated.clone());
        by_class.insert(schema.class.clone(), generated);
    }
    for manual in &overrides.manual_types {
        let base = sanitize_pascal(&manual.simple_name);
        let mut rust_name = if base_counts.get(&base).copied().unwrap_or_default() > 1 {
            match (manual.bid, manual.cid) {
                (Some(bid), Some(cid)) => format!("{base}Bid{bid}Cid{cid}"),
                _ => format!("{base}Manual"),
            }
        } else {
            base
        };
        if used_names.contains_key(&rust_name) {
            rust_name = format!("{rust_name}Manual");
        }
        *used_names.entry(rust_name.clone()).or_default() += 1;
        by_simple.insert(
            manual.simple_name.clone(),
            GeneratedType {
                rust_name,
                bid: manual.bid,
                cid: manual.cid,
            },
        );
    }
    GeneratedTypeIndex {
        by_simple,
        by_class,
    }
}

fn should_generate_reflective(schema: &MessageSchema) -> bool {
    schema.encoding.as_deref() == Some("MsgpackReflective")
        && schema.bid.is_some()
        && schema.cid.is_some()
        && schema
            .msgpack_fields_effective
            .iter()
            .all(|field| parse_java_type(&field.ty).is_some())
}

fn unique_type_name(schema: &MessageSchema, base_counts: &BTreeMap<String, usize>) -> String {
    let base = sanitize_pascal(&schema.simple_name);
    if base_counts.get(&base).copied().unwrap_or_default() > 1 {
        format!(
            "{base}Bid{}Cid{}",
            schema.bid.unwrap_or_default(),
            schema.cid.unwrap_or_default()
        )
    } else {
        base
    }
}

fn emit_descriptors(out: &mut String, schemas: &[MessageSchema]) {
    out.push_str("    #[derive(Debug, Clone, Copy, PartialEq, Eq)]\n");
    out.push_str("    pub enum MessageKind { Request, Response, Data, Unknown }\n\n");
    out.push_str("    #[derive(Debug, Clone, Copy, PartialEq, Eq)]\n");
    out.push_str(
        "    pub enum MessageEncoding { MsgpackReflective, ManualOrEmptyPayload, Unknown }\n\n",
    );
    out.push_str("    #[derive(Debug, Clone, Copy, PartialEq, Eq)]\n");
    out.push_str("    pub struct FieldDescriptor {\n");
    out.push_str("        pub name: &'static str,\n");
    out.push_str("        pub java_type: &'static str,\n");
    out.push_str("        pub order: i32,\n");
    out.push_str("        pub since: i32,\n");
    out.push_str("    }\n\n");
    out.push_str("    #[derive(Debug, Clone, Copy, PartialEq, Eq)]\n");
    out.push_str("    pub struct MessageDescriptor {\n");
    out.push_str("        pub class_name: &'static str,\n");
    out.push_str("        pub simple_name: &'static str,\n");
    out.push_str("        pub package: Option<&'static str>,\n");
    out.push_str("        pub source: Option<&'static str>,\n");
    out.push_str("        pub kind: MessageKind,\n");
    out.push_str("        pub encoding: MessageEncoding,\n");
    out.push_str("        pub bid: Option<u16>,\n");
    out.push_str("        pub cid: Option<u16>,\n");
    out.push_str("        pub fields: &'static [FieldDescriptor],\n");
    out.push_str("    }\n\n");
    out.push_str("    pub static MESSAGE_DESCRIPTORS: &[MessageDescriptor] = &[\n");

    let mut sorted = schemas.to_vec();
    sorted.sort_by(|a, b| {
        (
            a.bid.unwrap_or(u16::MAX),
            a.cid.unwrap_or(u16::MAX),
            &a.class,
        )
            .cmp(&(
                b.bid.unwrap_or(u16::MAX),
                b.cid.unwrap_or(u16::MAX),
                &b.class,
            ))
    });

    for schema in &sorted {
        out.push_str("        MessageDescriptor {\n");
        push_kv_str(out, "class_name", &schema.class, 12);
        push_kv_str(out, "simple_name", &schema.simple_name, 12);
        push_kv_option_str(out, "package", schema.package.as_deref(), 12);
        push_kv_option_str(out, "source", schema.source.as_deref(), 12);
        out.push_str(&format!(
            "            kind: {},\n",
            message_kind_expr(schema.message_kind.as_deref())
        ));
        out.push_str(&format!(
            "            encoding: {},\n",
            encoding_expr(schema.encoding.as_deref())
        ));
        push_kv_option_u16(out, "bid", schema.bid, 12);
        push_kv_option_u16(out, "cid", schema.cid, 12);
        out.push_str("            fields: &[\n");
        for field in sorted_fields(&schema.msgpack_fields_effective) {
            let (order, since) = field
                .msgpack
                .map(|msgpack| (msgpack.order, msgpack.since))
                .unwrap_or_default();
            out.push_str(&format!(
                "                FieldDescriptor {{ name: {}, java_type: {}, order: {order}, since: {since} }},\n",
                rust_literal(&field.name),
                rust_literal(&field.ty)
            ));
        }
        out.push_str("            ],\n");
        out.push_str("        },\n");
    }
    out.push_str("    ];\n\n");
}

fn emit_vec_helpers(out: &mut String) {
    out.push_str(
        r#"    fn write_vec_i8(out: &mut Vec<u8>, values: &[i8]) -> Result<()> {
        write_array_len(out, values.len())?;
        for value in values {
            write_i8(out, *value);
        }
        Ok(())
    }

    fn write_vec_i32(out: &mut Vec<u8>, values: &[i32]) -> Result<()> {
        write_array_len(out, values.len())?;
        for value in values {
            write_i32(out, *value);
        }
        Ok(())
    }

    fn write_vec_i64(out: &mut Vec<u8>, values: &[i64]) -> Result<()> {
        write_array_len(out, values.len())?;
        for value in values {
            write_i64(out, *value);
        }
        Ok(())
    }

    fn write_vec_string(out: &mut Vec<u8>, values: &[String]) -> Result<()> {
        write_array_len(out, values.len())?;
        for value in values {
            write_str(out, value)?;
        }
        Ok(())
    }

    fn read_vec_i8(reader: &mut MsgpackReader<'_>) -> Result<Vec<i8>> {
        let len = reader.read_array_len()?;
        let mut values = Vec::with_capacity(len);
        for _ in 0..len {
            values.push(reader.read_i8()?);
        }
        Ok(values)
    }

    fn read_vec_i32(reader: &mut MsgpackReader<'_>) -> Result<Vec<i32>> {
        let len = reader.read_array_len()?;
        let mut values = Vec::with_capacity(len);
        for _ in 0..len {
            values.push(reader.read_i32()?);
        }
        Ok(values)
    }

    fn read_vec_i64(reader: &mut MsgpackReader<'_>) -> Result<Vec<i64>> {
        let len = reader.read_array_len()?;
        let mut values = Vec::with_capacity(len);
        for _ in 0..len {
            values.push(reader.read_i64()?);
        }
        Ok(values)
    }

    fn read_vec_string(reader: &mut MsgpackReader<'_>) -> Result<Vec<String>> {
        let len = reader.read_array_len()?;
        let mut values = Vec::with_capacity(len);
        for _ in 0..len {
            values.push(reader.read_str()?);
        }
        Ok(values)
    }

"#,
    );
}

fn emit_typed_module(
    out: &mut String,
    schemas: &[MessageSchema],
    overrides: &CodegenOverrides,
    generated_types: &GeneratedTypeIndex,
) {
    out.push_str("    pub mod typed {\n");
    out.push_str("        use super::*;\n\n");

    let mut reflective = schemas
        .iter()
        .filter(|schema| should_generate_reflective(schema))
        .collect::<Vec<_>>();
    reflective.sort_by(|a, b| {
        (
            a.bid.unwrap_or(u16::MAX),
            a.cid.unwrap_or(u16::MAX),
            &a.class,
        )
            .cmp(&(
                b.bid.unwrap_or(u16::MAX),
                b.cid.unwrap_or(u16::MAX),
                &b.class,
            ))
    });

    for schema in reflective {
        let rust_name = &generated_types.by_class[&schema.class].rust_name;
        emit_reflective_type(out, schema, rust_name);
    }
    for manual in &overrides.manual_types {
        let rust_name = &generated_types.by_simple[&manual.simple_name].rust_name;
        emit_manual_type(out, manual, rust_name);
    }

    out.push_str("    }\n");
}

fn emit_reflective_type(out: &mut String, schema: &MessageSchema, rust_name: &str) {
    let fields = typed_fields(&schema.msgpack_fields_effective);

    out.push_str("        #[derive(Debug, Clone, PartialEq)]\n");
    out.push_str(&format!("        pub struct {rust_name} {{\n"));
    for field in &fields {
        out.push_str(&format!(
            "            pub {}: {},\n",
            field.rust_name,
            rust_type(&field.kind, field.optional)
        ));
    }
    out.push_str("        }\n\n");
    out.push_str(&format!("        impl {rust_name} {{\n"));
    out.push_str(&format!(
        "            pub const BID: u8 = {};\n",
        schema.bid.unwrap_or_default()
    ));
    out.push_str(&format!(
        "            pub const CID: u8 = {};\n",
        schema.cid.unwrap_or_default()
    ));
    out.push_str(&format!(
        "            pub const CLASS_NAME: &'static str = {};\n\n",
        rust_literal(&schema.class)
    ));

    out.push_str("            pub fn payload(&self) -> Result<Vec<u8>> {\n");
    out.push_str("                let mut out = Vec::new();\n");
    for field in &fields {
        emit_write_field(out, field, "out", 16);
    }
    out.push_str("                Ok(out)\n");
    out.push_str("            }\n\n");

    out.push_str("            pub fn decode(payload: &[u8]) -> Result<Self> {\n");
    out.push_str("                let mut reader = MsgpackReader::new(payload);\n");
    out.push_str("                Ok(Self {\n");
    for field in &fields {
        emit_read_field(out, field, "reader", 20);
    }
    out.push_str("                })\n");
    out.push_str("            }\n\n");
    out.push_str("            pub fn decode_prefix(payload: &[u8]) -> Result<Self> {\n");
    out.push_str("                Self::decode(payload)\n");
    out.push_str("            }\n");
    out.push_str("        }\n\n");
}

fn emit_manual_type(out: &mut String, manual: &ManualType, rust_name: &str) {
    out.push_str("        #[derive(Debug, Clone, PartialEq)]\n");
    out.push_str(&format!("        pub struct {rust_name} {{\n"));
    for field in &manual.fields {
        out.push_str(&format!(
            "            pub {}: {},\n",
            field.name, field.rust_type
        ));
    }
    out.push_str("        }\n\n");
    out.push_str(&format!("        impl {rust_name} {{\n"));
    if let Some(bid) = manual.bid {
        out.push_str(&format!("            pub const BID: u8 = {bid};\n"));
    }
    if let Some(cid) = manual.cid {
        out.push_str(&format!("            pub const CID: u8 = {cid};\n"));
    }
    if let Some(kind) = &manual.message_kind {
        out.push_str(&format!(
            "            pub const MESSAGE_KIND: &'static str = {};\n",
            rust_literal(kind)
        ));
    }
    out.push_str("\n            pub fn payload(&self) -> Result<Vec<u8>> {\n");
    out.push_str("                let mut out = Vec::new();\n");
    for field in &manual.fields {
        emit_manual_write(out, field, "out", 16);
    }
    out.push_str("                Ok(out)\n");
    out.push_str("            }\n");
    out.push_str("        }\n\n");
}

fn emit_facade_modules(
    out: &mut String,
    overrides: &CodegenOverrides,
    generated_types: &GeneratedTypeIndex,
) {
    for module in &overrides.modules {
        out.push_str(&format!("pub mod {} {{\n", sanitize_snake(&module.name)));
        let mut exported_types = Vec::new();
        for export in &module.exports {
            if let Some(generated) = generated_types.by_simple.get(export) {
                exported_types.push(generated.rust_name.clone());
            }
        }
        exported_types.sort();
        exported_types.dedup();
        if !exported_types.is_empty() {
            out.push_str("    pub use super::generated::typed::{\n");
            for rust_name in exported_types {
                out.push_str(&format!("        {rust_name},\n"));
            }
            out.push_str("    };\n\n");
        }
        for constant in &module.constants {
            emit_module_constant(out, constant, generated_types);
        }
        out.push_str("}\n\n");
    }
}

fn emit_module_constant(
    out: &mut String,
    constant: &ModuleConstant,
    generated_types: &GeneratedTypeIndex,
) {
    if let Some(literal) = &constant.literal {
        let ty = constant.ty.as_deref().unwrap_or("u8");
        out.push_str(&format!(
            "    pub const {}: {ty} = {literal};\n",
            constant.name
        ));
        return;
    }

    let Some(message) = constant.message.as_deref() else {
        return;
    };
    let Some(generated) = generated_types.by_simple.get(message) else {
        return;
    };
    let value = match constant.value.as_deref() {
        Some("bid") => generated.bid,
        Some("cid") => generated.cid,
        Some("request_cid") => generated.cid.map(|cid| cid & 0x7f),
        _ => None,
    };
    if let Some(value) = value {
        out.push_str(&format!("    pub const {}: u8 = {value};\n", constant.name));
    }
}

#[derive(Debug, Clone)]
struct TypedField {
    rust_name: String,
    kind: ValueKind,
    optional: bool,
}

fn typed_fields(fields: &[FieldSchema]) -> Vec<TypedField> {
    let mut seen = HashMap::<String, usize>::new();
    sorted_fields(fields)
        .into_iter()
        .filter_map(|field| {
            let kind = parse_java_type(&field.ty)?;
            let base = sanitize_snake(&field.name);
            let seen_count = seen.entry(base.clone()).or_default();
            let rust_name = if *seen_count == 0 {
                base
            } else {
                format!("{base}_{}", *seen_count + 1)
            };
            *seen_count += 1;
            Some(TypedField {
                rust_name,
                kind,
                optional: field
                    .msgpack
                    .map(|msgpack| msgpack.since > 0)
                    .unwrap_or_default(),
            })
        })
        .collect()
}

fn sorted_fields(fields: &[FieldSchema]) -> Vec<FieldSchema> {
    let mut fields = fields
        .iter()
        .cloned()
        .enumerate()
        .collect::<Vec<(usize, FieldSchema)>>();
    fields.sort_by_key(|(idx, field)| {
        (
            field
                .msgpack
                .map(|msgpack| msgpack.order)
                .unwrap_or_default(),
            *idx,
        )
    });
    fields.into_iter().map(|(_, field)| field).collect()
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ValueKind {
    I8,
    I16,
    I32,
    I64,
    Bool,
    String,
    Bin,
    F32,
    F64,
    Vec(Box<ValueKind>),
}

fn parse_java_type(ty: &str) -> Option<ValueKind> {
    let ty = ty.trim();
    match ty {
        "byte" | "Byte" => Some(ValueKind::I8),
        "short" | "Short" => Some(ValueKind::I16),
        "int" | "Integer" => Some(ValueKind::I32),
        "long" | "Long" => Some(ValueKind::I64),
        "boolean" | "Boolean" => Some(ValueKind::Bool),
        "String" => Some(ValueKind::String),
        "byte[]" => Some(ValueKind::Bin),
        "float" | "Float" => Some(ValueKind::F32),
        "double" | "Double" => Some(ValueKind::F64),
        "int[]" => Some(ValueKind::Vec(Box::new(ValueKind::I32))),
        "long[]" => Some(ValueKind::Vec(Box::new(ValueKind::I64))),
        "String[]" => Some(ValueKind::Vec(Box::new(ValueKind::String))),
        _ => parse_java_list_type(ty),
    }
}

fn parse_java_list_type(ty: &str) -> Option<ValueKind> {
    let inner = ty
        .strip_prefix("List<")
        .or_else(|| ty.strip_prefix("ArrayList<"))?
        .strip_suffix('>')?;
    let inner = match inner {
        "Byte" => ValueKind::I8,
        "Integer" => ValueKind::I32,
        "Long" => ValueKind::I64,
        "String" => ValueKind::String,
        _ => return None,
    };
    Some(ValueKind::Vec(Box::new(inner)))
}

fn rust_type(kind: &ValueKind, optional: bool) -> String {
    let ty = match kind {
        ValueKind::I8 => "i8".to_string(),
        ValueKind::I16 => "i16".to_string(),
        ValueKind::I32 => "i32".to_string(),
        ValueKind::I64 => "i64".to_string(),
        ValueKind::Bool => "bool".to_string(),
        ValueKind::String => "String".to_string(),
        ValueKind::Bin => "Vec<u8>".to_string(),
        ValueKind::F32 => "f32".to_string(),
        ValueKind::F64 => "f64".to_string(),
        ValueKind::Vec(inner) => format!("Vec<{}>", rust_type(inner, false)),
    };
    if optional {
        format!("Option<{ty}>")
    } else {
        ty
    }
}

fn emit_write_field(out: &mut String, field: &TypedField, out_name: &str, indent: usize) {
    let prefix = " ".repeat(indent);
    if field.optional {
        out.push_str(&format!(
            "{prefix}if let Some(value) = &self.{} {{\n",
            field.rust_name
        ));
        emit_write_kind(out, &field.kind, "value", out_name, indent + 4, true);
        out.push_str(&format!("{prefix}}}\n"));
    } else {
        let access = format!("self.{}", field.rust_name);
        emit_write_kind(out, &field.kind, &access, out_name, indent, false);
    }
}

fn emit_write_kind(
    out: &mut String,
    kind: &ValueKind,
    access: &str,
    out_name: &str,
    indent: usize,
    by_ref: bool,
) {
    let prefix = " ".repeat(indent);
    let scalar = if by_ref {
        format!("*{access}")
    } else {
        access.to_string()
    };
    let by_ref_access = if by_ref {
        access.to_string()
    } else {
        format!("&{access}")
    };
    match kind {
        ValueKind::I8 => out.push_str(&format!("{prefix}write_i8(&mut {out_name}, {scalar});\n")),
        ValueKind::I16 => {
            out.push_str(&format!("{prefix}write_i16(&mut {out_name}, {scalar});\n"));
        }
        ValueKind::I32 => {
            out.push_str(&format!("{prefix}write_i32(&mut {out_name}, {scalar});\n"));
        }
        ValueKind::I64 => {
            out.push_str(&format!("{prefix}write_i64(&mut {out_name}, {scalar});\n"));
        }
        ValueKind::Bool => {
            out.push_str(&format!("{prefix}write_bool(&mut {out_name}, {scalar});\n"));
        }
        ValueKind::String => {
            out.push_str(&format!(
                "{prefix}write_str(&mut {out_name}, {by_ref_access})?;\n"
            ));
        }
        ValueKind::Bin => {
            out.push_str(&format!(
                "{prefix}write_bin(&mut {out_name}, {by_ref_access})?;\n"
            ));
        }
        ValueKind::F32 => {
            out.push_str(&format!("{prefix}write_f32(&mut {out_name}, {scalar});\n"));
        }
        ValueKind::F64 => {
            out.push_str(&format!("{prefix}write_f64(&mut {out_name}, {scalar});\n"));
        }
        ValueKind::Vec(inner) => match inner.as_ref() {
            ValueKind::I8 => {
                out.push_str(&format!(
                    "{prefix}write_vec_i8(&mut {out_name}, {by_ref_access})?;\n"
                ));
            }
            ValueKind::I32 => {
                out.push_str(&format!(
                    "{prefix}write_vec_i32(&mut {out_name}, {by_ref_access})?;\n"
                ));
            }
            ValueKind::I64 => {
                out.push_str(&format!(
                    "{prefix}write_vec_i64(&mut {out_name}, {by_ref_access})?;\n"
                ));
            }
            ValueKind::String => {
                out.push_str(&format!(
                    "{prefix}write_vec_string(&mut {out_name}, {by_ref_access})?;\n"
                ));
            }
            _ => unreachable!("unsupported vector element kind"),
        },
    }
}

fn emit_read_field(out: &mut String, field: &TypedField, reader: &str, indent: usize) {
    let prefix = " ".repeat(indent);
    let read_expr = read_expr(&field.kind, reader);
    if field.optional {
        out.push_str(&format!(
            "{prefix}{}: if {reader}.has_next() {{ Some({read_expr}) }} else {{ None }},\n",
            field.rust_name
        ));
    } else {
        out.push_str(&format!("{prefix}{}: {read_expr},\n", field.rust_name));
    }
}

fn read_expr(kind: &ValueKind, reader: &str) -> String {
    match kind {
        ValueKind::I8 => format!("{reader}.read_i8()?"),
        ValueKind::I16 => format!("{reader}.read_i16()?"),
        ValueKind::I32 => format!("{reader}.read_i32()?"),
        ValueKind::I64 => format!("{reader}.read_i64()?"),
        ValueKind::Bool => format!("{reader}.read_bool()?"),
        ValueKind::String => format!("{reader}.read_str()?"),
        ValueKind::Bin => format!("{reader}.read_bin()?"),
        ValueKind::F32 => format!("{reader}.read_f32()?"),
        ValueKind::F64 => format!("{reader}.read_f64()?"),
        ValueKind::Vec(inner) => match inner.as_ref() {
            ValueKind::I8 => format!("read_vec_i8(&mut {reader})?"),
            ValueKind::I32 => format!("read_vec_i32(&mut {reader})?"),
            ValueKind::I64 => format!("read_vec_i64(&mut {reader})?"),
            ValueKind::String => format!("read_vec_string(&mut {reader})?"),
            _ => unreachable!("unsupported vector element kind"),
        },
    }
}

fn emit_manual_write(out: &mut String, field: &ManualField, out_name: &str, indent: usize) {
    let prefix = " ".repeat(indent);
    let access = format!("self.{}", field.name);
    match field.write.as_str() {
        "i32" => out.push_str(&format!("{prefix}write_i32(&mut {out_name}, {access});\n")),
        "i64" => out.push_str(&format!("{prefix}write_i64(&mut {out_name}, {access});\n")),
        "bool" => out.push_str(&format!("{prefix}write_bool(&mut {out_name}, {access});\n")),
        "str" => out.push_str(&format!(
            "{prefix}write_str(&mut {out_name}, &{access})?;\n"
        )),
        "bin" => out.push_str(&format!(
            "{prefix}write_bin(&mut {out_name}, &{access})?;\n"
        )),
        "optional_i32" => {
            out.push_str(&format!("{prefix}if let Some(value) = {access} {{\n"));
            out.push_str(&format!("{prefix}    write_i32(&mut {out_name}, value);\n"));
            out.push_str(&format!("{prefix}}}\n"));
        }
        "array_bin_payload" => {
            out.push_str(&format!(
                "{prefix}write_array_len(&mut {out_name}, {access}.len())?;\n"
            ));
            out.push_str(&format!("{prefix}for value in &{access} {{\n"));
            out.push_str(&format!(
                "{prefix}    write_bin(&mut {out_name}, &value.payload()?)?;\n"
            ));
            out.push_str(&format!("{prefix}}}\n"));
        }
        "optional_array_bin_payload" => {
            out.push_str(&format!("{prefix}if let Some(values) = &{access} {{\n"));
            out.push_str(&format!(
                "{prefix}    write_array_len(&mut {out_name}, values.len())?;\n"
            ));
            out.push_str(&format!("{prefix}    for value in values {{\n"));
            out.push_str(&format!(
                "{prefix}        write_bin(&mut {out_name}, &value.payload()?)?;\n"
            ));
            out.push_str(&format!("{prefix}    }}\n"));
            out.push_str(&format!("{prefix}}}\n"));
        }
        "str_non_empty_or" => {
            let fallback = rust_literal(field.fallback.as_deref().unwrap_or_default());
            out.push_str(&format!(
                "{prefix}let value = if {access}.is_empty() {{ {fallback} }} else {{ {access}.as_str() }};\n"
            ));
            out.push_str(&format!("{prefix}write_str(&mut {out_name}, value)?;\n"));
        }
        other => panic!("unsupported manual write op {other}"),
    }
}

fn push_kv_str(out: &mut String, key: &str, value: &str, indent: usize) {
    out.push_str(&format!(
        "{}{key}: {},\n",
        " ".repeat(indent),
        rust_literal(value)
    ));
}

fn push_kv_option_str(out: &mut String, key: &str, value: Option<&str>, indent: usize) {
    let value = value
        .map(|value| format!("Some({})", rust_literal(value)))
        .unwrap_or_else(|| "None".to_string());
    out.push_str(&format!("{}{key}: {value},\n", " ".repeat(indent)));
}

fn push_kv_option_u16(out: &mut String, key: &str, value: Option<u16>, indent: usize) {
    let value = value
        .map(|value| format!("Some({value})"))
        .unwrap_or_else(|| "None".to_string());
    out.push_str(&format!("{}{key}: {value},\n", " ".repeat(indent)));
}

fn message_kind_expr(kind: Option<&str>) -> &'static str {
    match kind {
        Some("request") => "MessageKind::Request",
        Some("response") => "MessageKind::Response",
        Some("data") => "MessageKind::Data",
        _ => "MessageKind::Unknown",
    }
}

fn encoding_expr(encoding: Option<&str>) -> &'static str {
    match encoding {
        Some("MsgpackReflective") => "MessageEncoding::MsgpackReflective",
        Some("ManualOrEmptyPayload") => "MessageEncoding::ManualOrEmptyPayload",
        _ => "MessageEncoding::Unknown",
    }
}

fn sanitize_pascal(input: &str) -> String {
    let mut out = String::new();
    let mut uppercase_next = true;
    for ch in input.chars() {
        if ch.is_ascii_alphanumeric() {
            if uppercase_next {
                out.push(ch.to_ascii_uppercase());
            } else {
                out.push(ch);
            }
            uppercase_next = false;
        } else {
            uppercase_next = true;
        }
    }
    if out.is_empty() || out.as_bytes()[0].is_ascii_digit() {
        out.insert_str(0, "Msg");
    }
    out
}

fn sanitize_snake(input: &str) -> String {
    let mut out = String::new();
    let mut prev_is_lower_or_digit = false;
    for ch in input.chars() {
        if ch.is_ascii_alphanumeric() {
            let is_upper = ch.is_ascii_uppercase();
            if is_upper && prev_is_lower_or_digit && !out.ends_with('_') {
                out.push('_');
            }
            out.push(ch.to_ascii_lowercase());
            prev_is_lower_or_digit = ch.is_ascii_lowercase() || ch.is_ascii_digit();
        } else if !out.ends_with('_') {
            out.push('_');
            prev_is_lower_or_digit = false;
        }
    }
    while out.ends_with('_') {
        out.pop();
    }
    if out.is_empty() || out.as_bytes()[0].is_ascii_digit() {
        out.insert_str(0, "field_");
    }
    if is_rust_keyword(&out) {
        out.push('_');
    }
    out
}

fn is_rust_keyword(value: &str) -> bool {
    matches!(
        value,
        "as" | "break"
            | "const"
            | "continue"
            | "crate"
            | "else"
            | "enum"
            | "extern"
            | "false"
            | "fn"
            | "for"
            | "if"
            | "impl"
            | "in"
            | "let"
            | "loop"
            | "match"
            | "mod"
            | "move"
            | "mut"
            | "pub"
            | "ref"
            | "return"
            | "self"
            | "Self"
            | "static"
            | "struct"
            | "super"
            | "trait"
            | "true"
            | "type"
            | "unsafe"
            | "use"
            | "where"
            | "while"
            | "async"
            | "await"
            | "dyn"
    )
}

fn rust_literal(value: &str) -> String {
    format!("{value:?}")
}

fn stable_hash(value: &str) -> u32 {
    let mut hash = 0x811c_9dc5u32;
    for byte in value.as_bytes() {
        hash ^= u32::from(*byte);
        hash = hash.wrapping_mul(0x0100_0193);
    }
    hash
}
